// Builds draft.zh-Hant.csv for this draft: unchanged rows from the approved cases.zh-Hant.csv, new and modified rows
// (all generated by build-draft.ts from the sheets) translated line by line by pattern. Then:
//   node scripts/zh-copy.ts pdr/cinematic-reel-recommendation android --draft 20261125-115636 adopt --from <this dir>/draft.csv
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseCsv, toCsv } from '../../../../../../scripts/lib/csv.ts';

const here = dirname(fileURLToPath(import.meta.url));
const plat = join(here, '../..');
const read = (p: string) => parseCsv(readFileSync(p, 'utf8').replace(/^﻿+/, ''));
const en = read(join(here, 'draft.csv'));
const zhOld = read(join(plat, 'cases.zh-Hant.csv'));
const zhHead = zhOld[0];
const oldById = new Map(zhOld.slice(1).map(r => [r[0], r]));
const H = en[0];
const CHG: Record<string, string> = { unchanged: '未變更', modified: '修改', new: '新增', removed: '刪除' };

const SECTION: Record<string, string> = { Language: '語言', 'Photo tips sheet': '拍照建議面板' };
const line = (s: string): string => {
  let m: RegExpMatchArray | null;
  if (s === 'PowerDirector signed in on the test account') return 'PowerDirector 已用測試帳號登入';
  if ((m = s.match(/^App language (.+) \(Android Settings › Apps › PowerDirector › Language; run: launch --lang (.+)\)$/))) return `App 語言為 ${m[1]}（Android 設定 › 應用程式 › PowerDirector › 語言；執行時用 launch --lang ${m[2]}）`;
  if (s === 'Cinematic Reel Creator open on its template page') return '已開啟 Cinematic Reel Creator 的 template 頁';
  if (s === 'Look at the first template card') return '看第一張 template 卡片';
  if (s === 'Swipe the cards left one at a time to the last card') return '把卡片一張一張往左滑到最後一張';
  if ((m = s.match(/^Tap the photo tips chip on the (「.+」) card$/))) return `點${m[1]}卡片上的拍照建議標籤`;
  if (s === 'Tap the button at the bottom of the sheet') return '點面板最下方的按鈕';
  if ((m = s.match(/^Tap 「View photo tips」 on the (「.+」) card$/))) return `點${m[1]}卡片上的「View photo tips」`;
  if (s === 'Tap 「Got it」') return '點「Got it」';
  if ((m = s.match(/^the cards come in this order: (.+)$/))) return `卡片依序為：${m[1].replace(/」, 「/g, '」、「')}`;
  if ((m = s.match(/^card (\d) reads (「.+?」) with the description (「.+」)$/))) return `第 ${m[1]} 張卡片顯示${m[2]}，說明為${m[3]}`;
  if (s === 'every name and description is whole, not cut off and not garbled') return '每個名稱和說明都完整顯示，沒有被截斷或亂碼';
  if ((m = s.match(/^the sheet's first sentence names the template as (「.+」)$/))) return `面板第一句裡的 template 名稱為${m[1]}`;
  if ((m = s.match(/^under the first heading: (.+)$/))) return `第一個標題下：${m[1].replace(/」, 「/g, '」、「')}`;
  if ((m = s.match(/^under the second heading: (.+) \(swipe the row left to read the third\)$/))) return `第二個標題下：${m[1].replace(/」, 「/g, '」、「')}（第三項要往左滑才看得到）`;
  if (s === 'the sheet closes, back on the template page') return '面板關閉，回到 template 頁';
  if (s === 'Every step: the two headings, the captions and the button are in the app language, whole, not cut off and not garbled') return '每個步驟：兩個標題、說明文字和按鈕都是 App 語言，完整顯示，沒有被截斷或亂碼';
  if ((m = s.match(/^Every step: each picture is the (JP|EN) picture/))) return `每個步驟：每張圖片都是試算表 Pic Link 清單裡該項目的 ${m[1]} 圖片（specs/2026-11-25/extracted/recommendation-pic-links.png）`;
  if (s.startsWith("Steps 1, 3, 5, 7, 9, 11: each item's picture")) return '步驟 1、3、5、7、9、11：每個項目的圖片都和 Cinestory CMS › Recommendation ›「Pic Link」裡同一項目旁的 EN 圖片相同（specs/2026-11-25/extracted/recommendation-pic-links.png）';
  if (s.startsWith('Steps 1, 3, 5, 7, 9, 11: an item that appears')) return '步驟 1、3、5、7、9、11：同一項目出現在多個 template 時，圖片都一樣；只有 Fast Cut 的「Rich Visual Details」用它自己的「for Fast Cut」圖片';
  if (s.startsWith('Steps 1, 3, 5, 7, 9, 11: no picture')) return '步驟 1、3、5、7、9、11：沒有空白、破圖、變形或預設佔位的圖片';
  throw new Error('no pattern: ' + s);
};
const cell = (s: string) => s.split('\n').map(l => {
  const n = l.match(/^(\d+)\. (.*)$/); if (n) return `${n[1]}. ${line(n[2])}`;
  const st = l.match(/^Step (\d+): (.*)$/); if (st) return `步驟 ${st[1]}：${line(st[2])}`;
  return line(l);
}).join('\n');
const note = (s: string) => {
  let m: RegExpMatchArray | null;
  if ((m = s.match(/^Cinestory CMS › Order (「.+?」) \(by app language, user 2026-11-25\); › Template Name Localization column (\S+); › Template Description Localization rows 2–7 column \S+\. If the app's language list has no (.+), record Blocked \(test-data\) and name the list\. Restore English after the language block\.$/)))
    return `Cinestory CMS › Order ${m[1]}（依 App 語言，使用者 2026-11-25 裁定）；› Template Name Localization 的 ${m[2]} 欄；› Template Description Localization 第 2–7 列的 ${m[2]} 欄。若 App 的語言清單沒有 ${m[3]}，記為 Blocked（test-data）並寫出清單內容。語言組跑完後改回英文。`;
  if ((m = s.match(/^I2V Recommendation › Localization column (\S+) \(CMS items #54–67\); .* Run right after the (.+) cards row, same language\.$/)))
    return `I2V Recommendation › Localization 的 ${m[1]} 欄（CMS 項目 #54–67）；Fast Cut 的「Rich Visual Details」是項目 #56（…_fast_cut），說明文字依使用者 2026-11-25 裁定。標籤和第一句本身的文字是 Q-2（已開 DRA262611P0290）：記錄其語言，不判失敗。緊接在 ${m[2]} 的卡片列之後跑，語言不變。`;
  if (s.startsWith('TR261019-014 「Thumbnail」')) return 'TR261019-014 的「Thumbnail」連結 = Cinestory CMS gid 1744053327（Recommendation）。共 14 個項目（#54–67）：用肉眼和存下的試算表圖片比對。';
  throw new Error('no note pattern: ' + s.slice(0, 80));
};
const reason = (s: string) => ({
  'REQ-006: TR260923-022 (Cinestory template info) — card order, names and descriptions per app language': 'REQ-006：TR260923-022（Cinestory template 資訊）— 各 App 語言的卡片順序、名稱與說明',
  'REQ-006: TR261019-014 Localization — captions and template names in the sheet per app language': 'REQ-006：TR261019-014 Localization — 各 App 語言的面板說明文字與 template 名稱',
  'REQ-006: TR261019-014 lists the thumbnails; no row compared the pictures with the sheet': 'REQ-006：TR261019-014 列出縮圖，原本沒有任何一列拿圖片和試算表比對',
  'REQ-006: the I2V Recommendation › Localization tab gives every caption per language (Q-2 partly answered); the row now reads all six templates': 'REQ-006：I2V Recommendation › Localization 分頁給了每種語言的說明文字（Q-2 部分已解答）；本列改成讀完六個 template',
} as Record<string, string>)[s] ?? (() => { throw new Error('no reason: ' + s); })();

const out = [zhHead];
for (const r of en.slice(1)) {
  const o = Object.fromEntries(H.map((k, i) => [k, r[i] ?? '']));
  if (o.Change === 'unchanged') {
    const z = oldById.get(o.ID); if (!z) throw new Error('no zh for ' + o.ID);
    out.push([...z.slice(0, 8), CHG.unchanged, '']); continue;
  }
  out.push([o.ID, SECTION[o.Section] ?? o.Section, cell(o.Precondition), cell(o.Action), cell(o['Expected Result']), o.Priority, o['Spec Ref'], note(o.Notes), CHG[o.Change], reason(o['Change Reason'])]);
}
writeFileSync(join(here, 'draft.zh-Hant.csv'), toCsv(out));
console.log(`draft.zh-Hant.csv: ${out.length - 1} rows`);
